insert into public.bw_letter_templates (key,title,signed_by,body,sort) values
('C0','Covering request email','Sent to the official who will handle the letter, not to the signatory.',E'Subject: Request for a letter of support — [event name] bid, deadline [date]\n\nDear [Name],\n\n[Client organisation] is bidding to host the [event name] in [city] in [year]. The bid is submitted to [issuing body] on [date].\n\nWe are writing to request a letter of support from [office/minister]. To make this as straightforward as possible, we have attached a draft letter for review, prepared in the terms we believe are appropriate for your office. Please amend it in any way you see fit — it is offered as a starting point, not a text to be adopted unchanged.\n\nWhat the bid needs from [office] specifically:\n   • [Specific ask 1]\n   • [Specific ask 2]\n\nThe evaluators place significant weight on demonstrated national support, and a letter that names specific commitments carries considerably more weight than a general endorsement.\n\nWe would be grateful to receive the signed letter, on letterhead, by [date — two weeks before your real deadline]. A scanned PDF is sufficient for submission; the original can follow.\n\nA two-page bid brief is attached for context. I am available at [phone] to discuss, and can attend in person if that would help.\n\nWith thanks,\n[Name, title, organisation]',0),
('C1','Government ministry — commitment and facilitation','Minister or Permanent Secretary of the sponsoring ministry',E'[Ministry letterhead]\n[Date]\n\nThe President\nThe Secretariat\n[Issuing body]\n[Address]\n\nRE: [EVENT NAME] [YEAR] — LETTER OF SUPPORT FROM THE GOVERNMENT OF [COUNTRY]\n\nOn behalf of the Government of [country], I write in full support of the bid by [client organisation] to host the [event name] in [city] in [year].\n\n[Event subject area] is a national priority for [country]. It is identified in [national development strategy / sector policy, with reference] as [brief description of the policy link]. Hosting this congress would advance that agenda directly by [one specific, concrete outcome].\n\nThe Government of [country] commits to the following in support of the event:\n\n1.  Facilitation of entry for all accredited delegates, speakers and exhibitors, including [expedited visa processing / visa-on-arrival arrangements / fee waivers], coordinated through the Department of Immigration.\n2.  Customs facilitation and duty exemption for exhibition materials and event equipment imported temporarily for the congress.\n3.  [Specific financial or in-kind commitment with a stated value, e.g. hosting of the opening ceremony, provision of the conference venue, a contribution of USD X].\n4.  Protocol support for visiting dignitaries and the participation of [named senior representative] in the opening ceremony.\n5.  Coordination across relevant ministries and agencies through [named office], which will act as the Government''s single point of contact for the organisers.\n\n[Country] has hosted [reference to comparable events hosted, if any], and the necessary infrastructure, security arrangements and health services are in place to receive an international gathering of this scale.\n\nThe Government stands ready to work with [issuing body] and with the local organising committee to ensure a congress of the standard your members expect.\n\nYours faithfully,\n\n[Name]\n[Title]\n[Ministry]',1),
('C2','National convention bureau','Chief Executive of the national or city convention bureau',E'[Bureau letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — CONVENTION BUREAU SUPPORT\n\nThe [bureau name] is the official body responsible for attracting and supporting international business events in [country/city]. We write in full support of the bid to host the [event name] in [city] in [year], and confirm the following support package.\n\nBid stage:\n   •  Coordination of venue and accommodation availability across [n] partner properties\n   •  Preparation of destination content, imagery and data for the bid submission\n   •  [Contribution towards bid production costs / hosting of the site inspection]\n\nOn award:\n   •  [Subvention or support grant of USD X, subject to the conditions set out in our standard support framework]\n   •  Delegate welcome services, including [airport welcome desk / city information desk / delegate discount programme]\n   •  Assistance with government liaison, permits and protocol\n   •  Promotional support through our channels and at [named trade events]\n   •  [Complimentary provision of X]\n\nThe [bureau] has supported [n] international congresses in [city] over the past [n] years, including [named examples with delegate numbers]. Our team works alongside organisers from award through to post-event reporting.\n\nWe would be delighted to welcome [association name] to [city].\n\nYours sincerely,\n\n[Name], Chief Executive\n[Bureau]',2),
('C3','City or municipal authority','Mayor, Town Clerk or head of the municipal authority',E'[City letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — CITY OF [CITY] LETTER OF WELCOME AND SUPPORT\n\nIt is my pleasure to extend the City of [city]''s full support to the bid to host the [event name] in [year].\n\n[City] has established itself as [one sentence of positioning grounded in fact — a sector, an institution, an infrastructure asset]. The [event name] aligns with the City''s [named strategy or plan] and would bring [specific benefit].\n\nThe City commits to:\n\n1.  A civic reception for delegates hosted at [venue] during the congress.\n2.  Facilitation of all municipal permits, licences and approvals required for the event and its associated activities, at [no cost / reduced cost].\n3.  Coordination of city services during the congress period, including [traffic management, signage, cleaning, security liaison].\n4.  [Access to municipal venues or public spaces for social functions].\n5.  Participation of the Mayor in the opening ceremony.\n\nOur municipal services, emergency response and public health capacity are prepared to support an international gathering of this size, and my office will designate a named coordinator to work with the organisers from award through delivery.\n\n[City] would be honoured to host your delegates.\n\nYours sincerely,\n\n[Name]\nMayor / Town Clerk, City of [city]',3),
('C4','National or regional professional association','President or Executive Director of the national body in the events field',E'[Association letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — ENDORSEMENT AND COMMITMENT FROM [NATIONAL ASSOCIATION]\n\nThe [national association], representing [n] members across [country/region], writes in full support of the bid to host the [event name] in [city] in [year].\n\nOur members have participated in [event name] since [year], most recently sending [n] delegates to [previous host city]. Hosting the congress in [country] would allow a far larger number of professionals from [region] to participate — many of whom have never been able to attend because of travel cost and distance. We estimate that [n] additional delegates from [country] and the surrounding region would attend.\n\nThe association commits to:\n\n1.  Active promotion of the congress to our full membership and to our counterpart associations in [list countries], from award through to the event.\n2.  Provision of [n] members to serve on the local organising committee, including [named role].\n3.  Support in identifying and securing regional speakers, content contributors and session chairs.\n4.  [Specific contribution — a hosted session, a delegate bursary scheme, a pre-congress workshop].\n5.  Assistance in engaging national institutions and regulatory bodies in the event programme.\n\nWe believe this congress in [country] would meaningfully advance [association]''s presence in a region where its membership has significant room to grow.\n\nYours faithfully,\n\n[Name], President\n[National association]',4),
('C5','Venue — hold and letter of intent','Venue Sales Director or General Manager',E'[Venue letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — CONFIRMATION OF AVAILABILITY AND LETTER OF INTENT\n\n[Venue name] confirms that it holds availability for the [event name] on the following basis.\n\nDates held: [dates], with [n] set-up days prior and [n] breakdown days following.\nHold status: [First option / provisional hold], valid until [date].\n\nSpaces reserved:\n   •  [Plenary hall] — [n] delegates, theatre style\n   •  [n] breakout rooms — capacities [range]\n   •  Exhibition area — [n] square metres\n   •  Registration, catering and organiser office space as required\n\nTechnical provision included: [internet bandwidth of n Mb/s to the plenary; AV specification; power provision; accessibility features].\n\nIndicative rate: [amount and basis]. [Or: The venue is offered at no charge subject to the conditions set out below.]\n\nConditions: [minimum catering spend / accommodation block requirement / confirmation deadline].\n\n[Venue] has hosted [named comparable events] and holds [relevant certifications]. Our team would work with the organisers from award through delivery.\n\nWe confirm our intent to contract on these terms should the bid be successful, subject to a definitive agreement.\n\nYours sincerely,\n\n[Name], [Title]\n[Venue]',5),
('C6','Accommodation — provisional block','Director of Sales at each property, or the bureau for a consortium',E'[Hotel or bureau letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — PROVISIONAL ACCOMMODATION BLOCK\n\n[Property / consortium] confirms provisional room availability for the [event name], [dates].\n\nRooms held: [n] rooms per night across [dates], comprising [breakdown by room type].\nCategory: [star rating]. Distance from venue: [n] km\n[n] minutes by [mode].\nIndicative rate: [amount] per room per night, [inclusive/exclusive] of breakfast and applicable taxes.\nRate validity: rates confirmed for [year]; rates for [event year] to be confirmed no later than [date] and will not exceed [indexation basis].\nRelease date: [date].\n\n[Where a consortium letter: the following properties participate, with rooms and categories as tabulated.]\n\nWe confirm our intent to enter into a definitive accommodation agreement on these terms should the bid be successful.\n\nYours sincerely,\n\n[Name], Director of Sales\n[Property / consortium]',6),
('C7','Airline — carrier support','Country manager or corporate sales lead',E'[Airline letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — AIRLINE SUPPORT\n\n[Airline] confirms its support for the bid to host the [event name] in [city] in [year].\n\n[Airline] operates [n] weekly services into [city] from [list hubs], connecting to [n] destinations across [regions]. Current schedules provide same-day connections from [key source markets].\n\nSubject to a successful bid and a definitive agreement, [airline] would offer:\n\n1.  Official carrier status for the congress, with a delegate discount of [n]% on published fares.\n2.  A dedicated booking channel and event code for delegates.\n3.  [Additional baggage allowance for exhibitors / complimentary tickets for keynote speakers / lounge access for the organising committee].\n4.  Promotion of the congress through [airline channels].\n\nWe would be pleased to work with the organisers to ensure convenient access for delegates from across [region].\n\nYours sincerely,\n\n[Name], [Title]\n[Airline]',7),
('C8','Academic or research institution — content and legacy partner','Vice-Chancellor, Dean or Institute Director',E'[Institution letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — INSTITUTIONAL PARTNERSHIP\n\n[Institution] writes in support of the bid to host the [event name] in [city] in [year], and confirms its commitment to participate as a content and legacy partner.\n\n[Institution] is [one factual sentence: standing, scale, relevant department or research strength, with a verifiable reference].\n\nWe commit to:\n\n1.  Contribution of [n] scientific or technical papers and the participation of [n] researchers as speakers and session chairs.\n2.  Hosting of [a pre-congress workshop / a field visit / a satellite symposium] at our [named facility].\n3.  Participation of [named senior academic] on the scientific or programme committee.\n4.  A legacy commitment: [specific and measurable — e.g. a training programme for n practitioners in the year following the congress, a research collaboration with named partners, a published proceedings volume].\n5.  [Student volunteer participation / discounted student registration support].\n\nThe congress would strengthen [country]''s research capacity in [field] and connect our researchers to an international community they currently reach only through travel abroad.\n\nYours sincerely,\n\n[Name], [Title]\n[Institution]',8),
('C9','Private sector sponsor — commitment','Marketing, corporate affairs or country director',E'[Company letterhead]\n[Date]\n\nRE: [EVENT NAME] [YEAR] — SPONSORSHIP COMMITMENT\n\n[Company] confirms its intention to support the [event name] should the bid to host in [city] in [year] be successful.\n\nSubject to a definitive sponsorship agreement, [company] commits to:\n\n   •  A financial contribution of [currency and amount] at [tier] level.\n   •  [In-kind provision: describe with its market value.]\n   •  [Promotion of the congress through company channels and to its customer base.]\n\nThis commitment is valid until [date] and is conditional on the congress being awarded to [city] and being held within the dates indicated.\n\n[One or two sentences on why the company is supporting — sector alignment, market presence, corporate responsibility commitment. A stated reason is more credible than an unexplained cheque.]\n\nYours sincerely,\n\n[Name], [Title]\n[Company]',9)
